# Idea: Use a binary search on the value range combined with counting to determine the k-th smallest element.

```python
def solve(nums, k):
    low, high = min(nums), max(nums)
    while low <= high:
        mid = (low + high) // 2
        count_less = 0
        count_equal = 0
        for num in nums:
            if num < mid:
                count_less += 1
            elif num == mid:
                count_equal += 1
        if count_less < k <= count_less + count_equal:
            return mid
        elif count_less >= k:
            high = mid - 1
        else:
            low = mid + 1
    return low
```

