def solve(nums, k):
    def count_less_equal(arr, x):
        return sum(1 for val in arr if val <= x)

    def count_less(arr, x):
        return sum(1 for val in arr if val < x)

    left, right = min(nums), max(nums)
    result = right
    while left <= right:
        mid = (left + right) // 2
        count_le = count_less_equal(nums, mid)
        count_lt = count_less(nums, mid)
        if count_lt < k <= count_le:
            result = mid
            right = mid - 1
        elif k > count_le:
            left = mid + 1
        else:
            right = mid - 1
    return result
```

