# Idea: Use a modified selection algorithm that partitions the list around random pivots while maintaining counts of smaller and equal elements to avoid fully sorting or using heaps.

```python
import random

def solve(nums, k):
    if len(nums) == 1:
        return nums[0]

    def quick_choose(arr, kth):
        if len(arr) == 1:
            return arr[0]

        # Choose pivot randomly to avoid worst-case patterns
        pivot = random.choice(arr)
        smaller, equal, larger = [], [], []

        for x in arr:
            if x < pivot:
                smaller.append(x)
            elif x == pivot:
                equal.append(x)
            else:
                larger.append(x)

        count_smaller = len(smaller)
        count_equal = len(equal)

        if kth <= count_smaller:
            return quick_choose(smaller, kth)
        elif kth <= count_smaller + count_equal:
            return pivot
        else:
            return quick_choose(larger, kth - count_smaller - count_equal)

    return quick_choose(nums, k)
```

