def solve(nums, k):
    if len(nums) == 1:
        return nums[0]

    min_val, max_val = min(nums), max(nums)
    if min_val == max_val:
        return min_val

    n = len(nums)
    bucket_range = max(1, (max_val - min_val) // n)
    buckets = [[] for _ in range(n + 1)]

    for x in nums:
        idx = (x - min_val) // (bucket_range + 1)
        buckets[idx].append(x)

    count = 0
    for bucket in buckets:
        if bucket:
            bucket_min, bucket_max = min(bucket), max(bucket)
            bucket_size = len(bucket)
            if count < k <= count + bucket_size:
                if bucket_min == bucket_max:
                    return bucket_min
                # Recursively solve within the bucket
                return solve(bucket, k - count)
            count += bucket_size
    return max_val
