def solve(nums, k):
    if len(nums) == 1:
        return nums[0]

    min_val, max_val = min(nums), max(nums)
    if min_val == max_val:
        return min_val

    n = len(nums)
    # Number of buckets is sqrt(n), minimum 2
    num_buckets = max(2, int(n ** 0.5))
    bucket_range = (max_val - min_val) / num_buckets
    buckets = [[] for _ in range(num_buckets)]

    # Distribute numbers into buckets
    for x in nums:
        if x == max_val:
            # Ensure max value goes to last bucket
            bucket_idx = num_buckets - 1
        else:
            bucket_idx = int((x - min_val) / bucket_range)
        buckets[bucket_idx].append(x)

    # Traverse buckets to find k-th smallest
    count = 0
    for bucket in buckets:
        if not bucket:
            continue
        if count + len(bucket) < k:
            count += len(bucket)
            continue
        # k-th element is in this bucket — recurse
        return solve(bucket, k - count)

    return max_val  # Fallback (should not reach here)
```

