def solve(nums, k):
    def tournament_min(arr):
        if len(arr) == 1:
            return arr[0]
        next_round = []
        for i in range(0, len(arr) - len(arr) % 2, 2):
            next_round.append(min(arr[i], arr[i+1]))
        if len(arr) % 2 == 1:
            next_round.append(arr[-1])
        return tournament_min(next_round)

    working = list(nums)
    for _ in range(k - 1):
        min_val = tournament_min(working)
        # Remove the first occurrence of min_val
        for i in range(len(working)):
            if working[i] == min_val:
                working.pop(i)
                break
    return tournament_min(working)
```

