def solve(nums, k):
    if k == 1:
        return min(nums)
    if k == len(nums):
        return max(nums)

    n = len(nums)
    # Create list of (value, original_index) for tracking
    arr = [(nums[i], i) for i in range(n)]

    # Build a binary tournament tree structure for comparisons
    # Each node will represent winner of a comparison
    while len(arr) > k:
        next_round = []
        # Process pairs
        i = 0
        while i < len(arr):
            if i == len(arr) - 1:
                next_round.append(arr[i])  # odd one out advances
            else:
                # Compare and take smaller
                if arr[i][0] <= arr[i+1][0]:
                    next_round.append(arr[i])
                else:
                    next_round.append(arr[i+1])
            i += 2
        arr = next_round

    # Now reconstruct the k-th smallest using elimination paths
    candidates = list(set(nums))
    candidates.sort()

    # Simulate finding k-th smallest by checking how many are smaller
    for val in candidates:
        smaller = 0
        equal = 0
        for x in nums:
            if x < val:
                smaller += 1
            elif x == val:
                equal += 1
        if smaller < k <= smaller + equal:
            return val
```

