        sample.sort()
        pivot = sample[len(sample) // 2]

        smaller, equal, larger = [], [], []
        for x in arr:
            if x < pivot:
                smaller.append(x)
            elif x == pivot:
                equal.append(x)
            else:
                larger.append(x)

        count_smaller = len(smaller)
        count_equal = len(equal)

        if k <= count_smaller:
            arr = smaller
        elif k <= count_smaller + count_equal:
            return pivot
        else:
            arr = larger
            k -= count_smaller + count_equal
    return arr[0]
