def solve(nums, k):
    def find_min_index(arr):
        if len(arr) == 1:
            return 0
        candidates = []
        for i in range(0, len(arr), 2):
            if i + 1 < len(arr):
                if arr[i] <= arr[i + 1]:
                    candidates.append(i)
                else:
                    candidates.append(i + 1)
            else:
                candidates.append(i)
        while len(candidates) > 1:
            next_candidates = []
            for i in range(0, len(candidates), 2):
                if i + 1 < len(candidates):
                    idx1, idx2 = candidates[i], candidates[i + 1]
                    if arr[idx1] <= arr[idx2]:
                        next_candidates.append(idx1)
                    else:
                        next_candidates.append(idx2)
                else:
                    next_candidates.append(candidates[i])
            candidates = next_candidates
        return candidates[0]

    working = list(nums)
    last_removed = None
    for _ in range(k):
        min_idx = find_min_index(working)
        last_removed = working[min_idx]
        working.pop(min_idx)
    return last_removed
