import random

def solve(nums, k):
    def select(arr, rank):
        if len(arr) == 1:
            return arr[0]

        # Sample up to 5 elements to choose a good pivot
        sample = random.sample(arr, min(5, len(arr)))
        pivot = sorted(sample)[len(sample) // 2]

        lows = [x for x in arr if x < pivot]
        highs = [x for x in arr if x > pivot]
        mids = len(arr) - len(lows) - len(highs)  # count of pivot values

        if rank < len(lows):
            return select(lows, rank)
        elif rank < len(lows) + mids:
            return pivot
        else:
            return select(highs, rank - len(lows) - mids)

    return select(nums, k - 1)
