# Idea: Use a tournament-like elimination method that repeatedly finds and removes the smallest element until the k-th smallest is reached, using a doubly linked list to efficiently skip over eliminated elements.
class Node:
    def __init__(self, val, index):
        self.val = val
        self.index = index
        self.prev = None
        self.next = None

def solve(nums, k):
    if k == 1:
        return min(nums)
    if k == len(nums):
        return max(nums)

    # Create doubly linked list of indices sorted by value, breaking ties by index
    nodes = [Node(nums[i], i) for i in range(len(nums))]
    nodes.sort(key=lambda x: (x.val, x.index))

    for i in range(len(nodes)):
        if i > 0:
            nodes[i].prev = nodes[i-1]
        if i < len(nodes) - 1:
            nodes[i].next = nodes[i+1]

    head = nodes[0]
    tail = nodes[-1]

    current = head
    for _ in range(k - 1):
        # Remove current node
        if current.prev:
            current.prev.next = current.next
        else:
            head = current.next
        if current.next:
            current.next.prev = current.prev
        else:
            tail = current.prev

        # Move to next node (which is the next smallest)
        current = current.next or tail

    return current.val
```

