# Idea: Use a balanced binary search tree simulation with node counts to find the k-th smallest element by traversing based on subtree sizes.
```python
def solve(nums, k):
    if len(nums) == 1:
        return nums[0]

    class Node:
        __slots__ = ('val', 'count', 'left', 'right', 'left_size')
        def __init__(self, val):
            self.val = val
            self.count = 1
            self.left = None
            self.right = None
            self.left_size = 0  # Total nodes in left subtree

    def insert(root, val):
        if not root:
            return Node(val), False
        node = root
        path = []
        while node:
            path.append(node)
            if val == node.val:
                node.count += 1
                return root, True
            elif val < node.val:
                node.left_size += 1
                if node.left is None:
                    node.left = Node(val)
                    return root, False
                node = node.left
            else:
                if node.right is None:
                    node.right = Node(val)
                    return root, False
                node = node.right
        return root, False

    root = None
    for x in nums:
        root, _ = insert(root, x)

    def kth_smallest(node, k):
        if not node:
            return None
        rank_left = node.left_size  
        rank_right = rank_left + node.count  
        if k <= rank_left:
            return kth_smallest(node.left, k)
        elif k <= rank_right:
            return node.val
        else:
            return kth_smallest(node.right, k - rank_right)

    return kth_smallest(root, k)
```

