# Idea: Use a tournament-like elimination strategy where elements are compared in pairs, keeping the smaller of each pair, recursively building a hierarchy to determine order without full sorting.
def solve(nums, k):
    def tournament_select(lst, k):
        if len(lst) == 1:
            return lst[0]
        if k == 1:
            return min(lst)
        if k == len(lst):
            return max(lst)

        # Create a new list by comparing adjacent elements and keeping the smaller one
        winners = []
        comparisons = []

        # Group elements into pairs and compare
        for i in range(0, len(lst), 2):
            if i + 1 < len(lst):
                if lst[i] <= lst[i + 1]:
                    winners.append(lst[i])
                    comparisons.append((lst[i], lst[i + 1]))
                else:
                    winners.append(lst[i + 1])
                    comparisons.append((lst[i + 1], lst[i]))
            else:
                winners.append(lst[i])

        # Recursively get the k-th smallest in the winner bracket
        if k <= len(winners):
            result = tournament_select(winners, k)
        else:
            # If k is in the losers, we need to collect candidates
            result = collect_kth_from_losers(lst, comparisons, k)

        return result

    def collect_kth_from_losers(full_list, comparisons, k):
        # Collect all elements that lost in comparisons, plus unpaired ones
        candidates = []
        used = [False] * len(full_list)

        for winner, loser in comparisons:
            # Find index of winner and mark it used, add loser
            for i, val in enumerate(full_list):
                if not used[i] and val == winner:
                    used[i] = True
                    break
            candidates.append(loser)

        # Add unpaired or unused elements (in case of duplicates)
        for i, val in enumerate(full_list):
            if not used[i]:
                candidates.append(val)

        # Sort only when necessary and take k-th smallest
        candidates.sort()
        return candidates[k - 1]

    return tournament_select(nums, k)
