    while min_val < max_val:
        bucket_size = max(1, (max_val - min_val) // len(nums))
        if bucket_size == 0:
            bucket_size = 1

        bucket_count = (max_val - min_val) // bucket_size + 1
        buckets = [[] for _ in range(bucket_count)]

        for x in nums:
            if x == max_val and bucket_size == 1:
                idx = bucket_count - 1
            else:
                idx = (x - min_val) // bucket_size
            if idx < 0:
                idx = 0
            if idx >= bucket_count:
                idx = bucket_count - 1
            buckets[idx].append(x)

        counts = [len(bucket) for bucket in buckets]
        total = 0
        target_idx = -1
        for i, cnt in enumerate(counts):
            total += cnt
            if total >= k:
                target_idx = i
                break

        if len(buckets[target_idx]) == 0:
            break

        if target_idx == 0 and counts[0] >= k:
            nums = buckets[0]
            max_val = min_val + bucket_size - 1
        elif target_idx > 0:
            k -= sum(counts[:target_idx])
            nums = buckets[target_idx]
            min_val = min_val + target_idx * bucket_size
            max_val = min_val + bucket_size - 1
            if target_idx == bucket_count - 1:
                max_val = max(nums)
        else:
            break

        if len(nums) == 1 or min_val == max_val:
            return nums[0]

    nums.sort()
