import random
def solve(nums, k):
    if k == 1:
        return min(nums)
    if k == len(nums):
        return max(nums)

    # Create list of (value, wins) where wins counts how many elements this has defeated
    competitors = [(x, 0) for x in nums]

    while len(competitors) > 1:
        if len(competitors) == 2:
            a_val, a_wins = competitors[0]
            b_val, b_wins = competitors[1]
            if a_val < b_val:
                a_wins += 1
                if a_wins >= k - 1:
                    return a_val
                else:
                    competitors = [competitors[1]]  # Keep loser with updated wins
                    competitors[0] = (b_val, b_wins + 1)
            else:
                b_wins += 1
                if b_wins >= k - 1:
                    return b_val
                else:
                    competitors = [competitors[0]]
                    competitors[0] = (a_val, a_wins + 1)
            break

        next_round = []
        # Shuffle to avoid ordered worst cases
        random.shuffle(competitors)

        # Pair up adjacent elements
        i = 0
        while i < len(competitors) - 1:
            a_val, a_wins = competitors[i]
            b_val, b_wins = competitors[i+1]
            if a_val <= b_val:
                next_round.append((a_val, a_wins + 1))
                # Promote loser only if it hasn't lost too much
                if b_wins < k - 1:
                    next_round.append((b_val, b_wins + 1))
            else:
                next_round.append((b_val, b_wins + 1))
                if a_wins < k - 1:
                    next_round.append((a_val, a_wins + 1))
            i += 2

        # If odd number, include last one if still competitive
        if i == len(competitors) - 1:
            val, wins = competitors[i]
            if wins < k:
                next_round.append((val, wins))

        # Filter out elements that have lost too many times (cannot be k-th smallest)
        next_round = [x for x in next_round if x[1] < k]

        # If only one remains, it's the answer
        if len(next_round) == 1:
            return next_round[0][0]

        competitors = next_round

    return competitors[0][0]
