# Idea: Use a recursive divide-and-conquer strategy that partitions elements into thirds (low, mid, high) based on adaptive pivots to avoid worst-case behavior of quickselect while not fully sorting.
def solve(nums, k):
    if len(nums) == 1:
        return nums[0]
    if k <= 0 or k > len(nums):
        raise ValueError("k out of valid range")
    low, mid, high = [], [], []
    pivot1 = nums[0]
    pivot2 = nums[-1]
    if pivot1 == pivot2 and len(nums) > 1:
        pivot2 = nums[len(nums)//2]
    pivot1, pivot2 = sorted([pivot1, pivot2])
    for x in nums:
        if x < pivot1:
            low.append(x)
        elif x <= pivot2:
            mid.append(x)
        else:
            high.append(x)
    if k <= len(low):
        return solve(low, k)
    elif k <= len(low) + len(mid):
        return solve(mid, k - len(low))
    else:
        return solve(high, k - len(low) - len(mid))
